const N=70;const particles=[];for(let i=0;i<N;i++){particles.push({x:Math.random()*W(),y:H()*0.55+Math.random()*H()*0.45,r:1+Math.random()*2.2,speed:0.15+Math.random()*0.35,phase:Math.random()*Math.PI*2,amp:8+Math.random()*18,trail:[]});}
const waves=[];for(let i=0;i<4;i++){waves.push({y:H()*0.15+i*18,amp:6+i*3,freq:0.006+i*0.001,phase:Math.random()*Math.PI*2,speed:0.15+i*0.05});}
let t=0;
function draw(){
 t+=0.016;
 ctx.clearRect(0,0,W(),H());
 const cx=W()/2, cy=H()/2, safeR=Math.min(W(),H())*0.28;
 for(const w of waves){
 ctx.beginPath();
 for(let x=0;x<=W();x+=6){
 const y=w.y+Math.sin(x*w.freq+t*w.speed+w.phase)*w.amp;
 if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
 }
 const grad=ctx.createLinearGradient(0,w.y-20,W(),w.y+20);
 grad.addColorStop(0,PALETTE[0]+'00');
 grad.addColorStop(0.5,PALETTE[1]+'55');
 grad.addColorStop(1,PALETTE[0]+'00');
 ctx.strokeStyle=grad;
 ctx.lineWidth=1.4;
 ctx.stroke();
 }
 for(const p of particles){
 p.y-=p.speed;
 p.phase+=0.01;
 const dx=Math.sin(p.phase)*p.amp*0.02;
 p.x+=dx;
 if(p.y< -20){p.y=H()+20;p.x=Math.random()*W();p.trail.length=0;}
 const dist=Math.hypot(p.x-cx,p.y-cy);
 let alpha=1;
 if(dist<safeR){alpha=Math.max(0.05,dist/safeR*0.5);}
 p.trail.push({x:p.x,y:p.y});
 if(p.trail.length>10)p.trail.shift();
 for(let i=0;i<p.trail.length;i++){
 const tp=p.trail[i];
 const ta=alpha*(i/p.trail.length)*0.5;
 ctx.beginPath();
 ctx.arc(tp.x,tp.y,p.r*0.7,0,Math.PI*2);
 ctx.fillStyle=PALETTE[2];
 ctx.globalAlpha=ta;
 ctx.fill();
 }
 ctx.globalAlpha=alpha;
 ctx.beginPath();
 ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
 const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r*4);
 g.addColorStop(0,PALETTE[1]);
 g.addColorStop(1,PALETTE[1]+'00');
 ctx.fillStyle=g;
 ctx.shadowBlur=6;
 ctx.shadowColor=PALETTE[1];
 ctx.fill();
 ctx.shadowBlur=0;
 ctx.globalAlpha=1;
 }
 requestAnimationFrame(draw);
}
draw();
